            <label>{{ $t('legacy.t_91cdcd88db53') }}（選填）<input v-model.trim="form.paymentReference" maxlength="120" :disabled="form.paymentMethod==='security_deposit'" :placeholder="form.paymentMethod==='security_deposit'?$t('legacy.t_9b64abbc22ab'):'可填寫銀行流水號或付款參考'"></label>
            <label>{{ $t('legacy.t_f8aa34f40d01') }}<input ref="proofInput" type="file" accept="application/pdf,image/jpeg,image/png" @change="selectProof"><small>{{ proof?.name || $t('legacy.t_b35320f63845') }}</small></label>
