      <dialog ref="batchDialog" class="rent-confirm-dialog rent-batch-dialog">
        <form @submit.prevent="submitBatchConfirm">
          <header><div><h3>一键确认租金收款</h3><p>已带入 {{ batchRows.length }} 笔账单，共计 RM {{ money(batchOutstanding) }}</p></div><button type="button" @click="closeBatchConfirm">×</button></header>
          <p v-if="batchError" class="rent-action-error" role="alert">{{ batchError }}</p>
