            <div class="rent-confirm-notice"><b>每笔账单将按当前欠款全额确认</b><span>批量确认会分别生成租金收款和收据记录；任意一笔失败时，本批次全部不入账。</span></div>
            <div class="rent-form-grid"><label>收款日期<input v-model="batchForm.receivedDate" type="date" :max="todayDate" required><small>会计实际收款日期</small></label><label>入账日期<input v-model="batchForm.postingDate" type="date" required><small>业主账单与前端余额归属日期</small></label></div>
            <label>付款方式<select v-model="batchForm.paymentMethod" required><option value="bank_transfer">银行转账</option><option value="online_payment">线上支付</option><option value="cash">现金</option><option value="cheque">支票</option><option value="security_deposit">扣租客押金</option></select></label>
            <label>银行 / 付款参考（选填）<input v-model.trim="batchForm.paymentReference" maxlength="120" :disabled="batchForm.paymentMethod==='security_deposit'" :placeholder="batchForm.paymentMethod==='security_deposit'?'无需填写':'可填写本批次银行流水号或付款参考'"></label>
            <label>确认备注<textarea v-model.trim="batchForm.note" maxlength="500" rows="3" required></textarea></label>
            <label>收支备注（选填）<textarea v-model.trim="batchForm.allocationNote" maxlength="500" rows="3" placeholder="本批租金记录共用的收款说明"></textarea></label>
            <label class="prepayment-choice"><input v-model="batchForm.reuseAllocationNote" type="checkbox"><span>后续同一房产的租金收款沿用此备注<small>本批次每笔记录都会保存该备注，之后仍可单独修改。</small></span></label>
          </div>
          <menu><button type="button" @click="closeBatchConfirm">取消</button><button class="primary-btn" type="submit" :disabled="batchSaving || !batchRows.length">{{ batchSaving ? '批量入账中…' : `一键确认 ${batchRows.length} 笔` }}</button></menu>
        </form>
      </dialog>

      <dialog ref="proofDialog" class="modal admin-finance-proof-dialog"><div class="modal-head"><div><h3>{{ $t('legacy.t_bf3848894d3f') }}</h3><small>{{ selectedRow?.latestProofName }}</small></div><button class="icon-close" @click="closeProof">×</button></div><div class="finance-proof-viewer"><div v-if="proofLoading" class="admin-owner-state">{{ $t('legacy.t_6ce3778a43cd') }}</div><img v-else-if="proofUrl&&selectedRow?.latestProofMimeType?.startsWith('image/')" :src="proofUrl"><iframe v-else-if="proofUrl&&selectedRow?.latestProofMimeType==='application/pdf'" :src="proofUrl"></iframe><div v-else class="admin-owner-state">{{ proofError||$t('legacy.t_7db08b273aa4') }}</div></div><menu><button @click="closeProof">{{ $t('legacy.t_ddc05404b0d6') }}</button></menu></dialog>
    </section>
  </div>
</template>

<script>
import { batchConfirmAdminRentCollections, confirmAdminRentCollection, fetchAdminRentCollectionProjects, fetchAdminRentCollections, fetchAdminRentProof, fetchAdminRentReceipt } from '../services/propertyApi';
import { formatDate } from '../utils/dateFormat';
const localToday=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10);};
export default {
  inject:['page'],
  data(){return{rows:[],selectedId:null,selectedIds:[],batchRows:[],pageNumber:1,pageSize:5,totalRows:0,totalPages:1,loading:false,errorMessage:'',requestSerial:0,todayDate:localToday(),form:{amount:'',receivedDate:localToday(),postingDate:localToday(),paymentMethod:'bank_transfer',payerName:'',paymentReference:'',note:'',allocationNote:'',reuseAllocationNote:true},batchForm:{receivedDate:localToday(),postingDate:localToday(),paymentMethod:'bank_transfer',paymentReference:'',note:'批量核对租金收款无误',allocationNote:'',reuseAllocationNote:true},proof:null,saving:false,batchSaving:false,actionError:'',batchError:'',proofLoading:false,proofUrl:'',proofError:''};},
  computed:{selectedRow(){return this.rows.find(r=>r.invoiceId===this.selectedId)||this.rows[0]||null;},selectedRows(){return this.rows.filter(row=>this.selectedIds.includes(row.invoiceId));},selectedOutstanding(){return this.selectedRows.reduce((sum,row)=>sum+Number(row.outstandingAmount||0),0);},batchOutstanding(){return this.batchRows.reduce((sum,row)=>sum+Number(row.outstandingAmount||0),0);},allRowsSelected(){return this.rows.length>0&&this.rows.every(row=>this.selectedIds.includes(row.invoiceId));},visiblePages(){const start=Math.max(1,Math.min(this.pageNumber-2,this.totalPages-4));return Array.from({length:Math.min(5,this.totalPages)},(_,i)=>start+i);},paymentProgress(){return !Number(this.selectedRow?.amountDue)?0:Math.min(100,Math.round(Number(this.selectedRow.amountPaid||0)/Number(this.selectedRow.amountDue)*100));},collectionNonce(){return this.page.adminRentCollectionNonce;},batchNonce(){return this.page.adminFinanceBatchNonce;},advanceRentPlan(){const row=this.selectedRow,amount=Number(this.form.amount||0);if(!row||!Number.isFinite(amount)||amount<=0)return null;let remaining=amount,month=this.monthStart(row.billingMonth),lastMonth=this.monthStart(row.leaseEndDate),months=0,last=null;while(remaining>0.005&&month&&lastMonth&&month<=lastMonth){const due=month===this.monthStart(row.billingMonth)?Number(row.outstandingAmount||0):this.monthlyInvoiceAmount(row,month);if(due>0){const paid=Math.min(remaining,due);months+=1;last={paid,due,remaining:Math.max(due-paid,0)};remaining-=paid;}month=this.addMonth(month);}return{months,last,exceeds:remaining>0.005};},advanceRentSummary(){const plan=this.advanceRentPlan;if(!plan)return '';if(plan.exceeds)return this.$t('tenancy.advanceRentExceedsLease');let text=this.$t('tenancy.advanceRentMonths',{months:plan.months});if(plan.last?.remaining>0.005)text+=` ${this.$t('tenancy.advanceRentPartial',{amount:this.money(plan.last.paid),due:this.money(plan.last.due),remaining:this.money(plan.last.remaining)})}`;return text;},afterStatusText(){const remaining=Number(this.selectedRow?.outstandingAmount||0)-Number(this.form.amount||0);if(this.advanceRentPlan?.exceeds)return this.$t('tenancy.advanceRentExceedsLease');return remaining<=0?'本期租金將標記為已收齊':`入帳後仍有 RM ${this.money(Math.max(remaining,0))} 待收`; }},
  watch:{'page.moduleSearch'(){this.resetLoad();},'page.globalSearch'(){this.resetLoad();},'page.projectFilter'(){this.resetLoad();},'page.statusFilter'(){this.resetLoad();},'page.dateStart'(){this.resetLoad();},'page.dateEnd'(){this.resetLoad();},pageSize(){this.pageNumber=1;this.loadData();},collectionNonce(v,p){if(v>p)this.$nextTick(this.openConfirm);},batchNonce(v,p){if(v>p)this.$nextTick(this.openBatchConfirm);},rows:{deep:true,handler(v){if(!v.some(r=>r.invoiceId===this.selectedId))this.selectedId=v[0]?.invoiceId||null;}}},
  mounted(){this.loadData();},beforeUnmount(){this.revokeProof();},
  methods:{
    displayDate(value){return formatDate(value);},
    async loadData(){const serial=++this.requestSerial,preferred=this.selectedId;this.loading=true;this.errorMessage='';try{const [response,projects]=await Promise.all([fetchAdminRentCollections({page:this.pageNumber,pageSize:this.pageSize,keyword:this.page.globalSearch||this.page.moduleSearch||'',projectName:String(this.page.projectFilter||'').includes('全部')?'':this.page.projectFilter,status:this.statusParam(this.page.statusFilter),startDate:this.page.dateStart,endDate:this.page.dateEnd}),fetchAdminRentCollectionProjects()]);if(serial!==this.requestSerial)return;this.rows=response.rows||[];this.totalRows=response.page?.totalRows||0;this.totalPages=response.page?.totalPages||1;this.pageNumber=response.page?.page||1;this.selectedId=this.rows.some(r=>r.invoiceId===preferred)?preferred:this.rows[0]?.invoiceId||null;this.selectedIds=this.selectedIds.filter(id=>this.rows.some(row=>row.invoiceId===id));this.page.adminFinanceProjects=projects||[];this.page.adminFinanceMetrics=this.metrics(response.summary||{});}catch(e){if(serial!==this.requestSerial)return;this.rows=[];this.selectedIds=[];this.errorMessage=e.message||'API request failed';this.page.adminFinanceMetrics=null;}finally{if(serial===this.requestSerial)this.loading=false;}},
    metrics(s){return[{label:'待收租金帳單',value:`${Number(s.outstandingCount||0)} 筆`,delta:`RM ${this.money(s.outstandingAmount)}`,trend:Number(s.outstandingCount)?'down':'up'},{label:'完全未支付',value:`${Number(s.unpaidCount||0)} 筆`,delta:'尚未收到任何款項',trend:Number(s.unpaidCount)?'down':'up'},{label:'部分支付',value:`${Number(s.partialCount||0)} 筆`,delta:'仍需繼續收款',trend:Number(s.partialCount)?'down':'up'},{label:'逾期帳單',value:`${Number(s.overdueCount||0)} 筆`,delta:'需要跟進',trend:Number(s.overdueCount)?'down':'up'},{label:'本月已收租金',value:`RM ${this.money(s.monthReceived)}`,delta:'已確認入帳',trend:'up'}];},
    resetLoad(){this.pageNumber=1;this.selectedIds=[];this.loadData();},goPage(n){if(n>=1&&n<=this.totalPages&&n!==this.pageNumber){this.pageNumber=n;this.selectedIds=[];this.loadData();}},selectAndConfirm(row){this.selectedId=row.invoiceId;this.$nextTick(this.openConfirm);},openDetails(row){this.selectedId=row.invoiceId;this.$nextTick(()=>this.$refs.detailDialog?.showModal());},closeDetails(){this.$refs.detailDialog?.close();},openConfirmFromDetails(){this.closeDetails();this.$nextTick(this.openConfirm);},goToTenancyFromDetails(){this.closeDetails();this.goToTenancy();},openProofFromDetails(){this.closeDetails();this.$nextTick(this.openProof);},togglePageRows(event){const ids=this.rows.map(row=>row.invoiceId);this.selectedIds=event.target.checked?[...new Set([...this.selectedIds,...ids])]:this.selectedIds.filter(id=>!ids.includes(id));},
    openConfirm(){if(!this.selectedRow)return;this.form={amount:Number(this.selectedRow.outstandingAmount||0).toFixed(2),receivedDate:localToday(),postingDate:this.monthStart(this.selectedRow.billingMonth)||localToday(),paymentMethod:'bank_transfer',payerName:this.selectedRow.tenantName||'',paymentReference:'',note:'',allocationNote:'',reuseAllocationNote:true};this.proof=null;this.actionError='';if(this.$refs.proofInput)this.$refs.proofInput.value='';this.$refs.confirmDialog?.showModal();},closeConfirm(){if(!this.saving)this.$refs.confirmDialog?.close();},showConfirmError(message){this.actionError=message;},selectProof(e){const f=e.target.files?.[0]||null;if(f&&(!['application/pdf','image/jpeg','image/png'].includes(f.type)||f.size>10*1024*1024)){this.showConfirmError('只支援 10MB 以內的 PDF、JPG 或 PNG 憑證');e.target.value='';this.proof=null;return;}this.proof=f;},
    async submitConfirm(){const amount=Number(this.form.amount);if(!Number.isFinite(amount)||amount<=0){this.showConfirmError('本次實收金額必須大於 0。');return;}if(this.form.paymentMethod==='security_deposit'&&amount>Number(this.selectedRow?.outstandingAmount||0)){this.showConfirmError(this.$t('tenancy.securityDepositCurrentOnly'));return;}if(this.advanceRentPlan?.exceeds){this.showConfirmError(this.$t('tenancy.advanceRentExceedsLease'));return;}this.saving=true;this.actionError='';try{const result=await confirmAdminRentCollection(this.selectedRow.invoiceId,{...this.form,paymentReference:this.form.paymentMethod==='security_deposit'?null:(this.form.paymentReference||null),amount:amount.toFixed(2)},this.proof);this.$refs.confirmDialog?.close();await this.loadData();this.page.showToast(`租金已確認入帳：${result.referenceNo}，收據已產生`);if(result.id) await this.downloadReceipt(result.id,result.receiptNo);}catch(e){this.showConfirmError(e.message||'租金確認失敗');}finally{this.saving=false;}},
    openBatchConfirm(){const selected=this.selectedRows.filter(row=>Number(row.outstandingAmount||0)>0);this.batchRows=(selected.length?selected:this.rows.filter(row=>Number(row.outstandingAmount||0)>0)).map(row=>({...row}));if(!this.batchRows.length){this.page.showToast('当前列表没有可确认的租金账单');return;}const postingDate=this.monthStart(this.batchRows[0]?.billingMonth)||localToday();this.batchForm={receivedDate:localToday(),postingDate,paymentMethod:'bank_transfer',paymentReference:'',note:'批量核对租金收款无误',allocationNote:'',reuseAllocationNote:true};this.batchError='';this.$refs.batchDialog?.showModal();},closeBatchConfirm(){if(!this.batchSaving)this.$refs.batchDialog?.close();},async submitBatchConfirm(){const invoiceIds=this.batchRows.map(row=>row.invoiceId);if(!invoiceIds.length)return;this.batchSaving=true;this.batchError='';const count=invoiceIds.length;try{await batchConfirmAdminRentCollections({invoiceIds,receivedDate:this.batchForm.receivedDate,postingDate:this.batchForm.postingDate,paymentMethod:this.batchForm.paymentMethod,paymentReference:this.batchForm.paymentMethod==='security_deposit'?null:(this.batchForm.paymentReference||null),note:this.batchForm.note,allocationNote:this.batchForm.allocationNote||null,reuseAllocationNote:this.batchForm.reuseAllocationNote});this.$refs.batchDialog?.close();this.selectedIds=[];this.batchRows=[];await this.loadData();this.page.showToast(`已批量确认 ${count} 笔租金收款`);}catch(e){this.batchError=e.message||'批量确认租金失败';}finally{this.batchSaving=false;}},
    async openProof(){if(!this.selectedRow?.latestProofDocumentId)return;this.revokeProof();this.proofLoading=true;this.proofError='';this.$refs.proofDialog?.showModal();try{const r=await fetchAdminRentProof(this.selectedRow.latestProofDocumentId);this.proofUrl=URL.createObjectURL(r.blob);}catch(e){this.proofError=e.message||'憑證載入失敗';}finally{this.proofLoading=false;}},closeProof(){this.$refs.proofDialog?.close();this.revokeProof();},revokeProof(){if(this.proofUrl)URL.revokeObjectURL(this.proofUrl);this.proofUrl='';},async downloadReceipt(id,receiptNo){try{const r=await fetchAdminRentReceipt(id);this.saveBlob(r.blob,`rent-receipt-${receiptNo||id}.pdf`);this.page.showToast('租金收據下載已開始');}catch(e){this.page.showToast(e.message||'租金收據下載失敗');}},saveBlob(blob,fileName){const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=fileName;link.style.display='none';document.body.appendChild(link);link.click();window.setTimeout(()=>{link.remove();URL.revokeObjectURL(url);},1000);},goToTenancy(){const k=this.selectedRow?.tenantName||'';this.page.selectModule('adminTenants');this.$nextTick(()=>{this.page.globalSearch=k;});},monthStart(v){return v?String(v).slice(0,10):'';},addMonth(v){const [year,month]=v.split('-').map(Number);return `${month===12?year+1:year}-${String(month===12?1:month+1).padStart(2,'0')}-01`;},monthlyInvoiceAmount(row,month){const monthlyRent=Number(row.monthlyRent||0);if(row.rentCalculationMethod!=='daily_prorated')return monthlyRent;const start=Math.max(new Date(`${row.leaseStartDate}T00:00:00Z`).getTime(),new Date(`${month}T00:00:00Z`).getTime());const monthEnd=new Date(`${month.slice(0,7)}-01T00:00:00Z`);monthEnd.setUTCMonth(monthEnd.getUTCMonth()+1);const end=Math.min(new Date(`${row.leaseEndDate}T00:00:00Z`).getTime(),monthEnd.getTime()-86400000);if(start>end)return 0;const days=Math.round((end-start)/86400000)+1;const daysInMonth=new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5,7)),0)).getUTCDate();return Math.max(Number((monthlyRent*days/daysInMonth).toFixed(2)),monthlyRent>0?0.01:0);},statusParam(v){return({'未支付':'unpaid','部分支付':'partial','已逾期':'overdue'})[v]||'';},statusLabel(v){return({unpaid:'未支付',partial:'部分支付',overdue:'已逾期'})[v]||v;},statusClass(v){return v==='partial'?'orange':v==='overdue'?'red':'gray';},paymentMethodLabel(v){return({bank_transfer:'銀行轉帳',online_payment:'線上支付',cash:'現金',cheque:'支票',security_deposit:this.$t('tenancy.securityDepositPayment')})[v]||v||'—';},monthLabel(v){return v?String(v).slice(0,7):'—';},money(v){return Number(v||0).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2});}
  }
};
</script>

